-- Dev Amazon ASINs (the /dp/ part of the seeded URLs), so the Creators API source has items to
-- refresh (scripts/mock-integrations.mjs answers for them), and source → retailer links.
insert into public.product_identifiers (variant_id, kind, value, retailer_id)
select o.variant_id, 'asin', substring(o.url from '/dp/([A-Z0-9]{10})'), o.retailer_id
  from public.retailer_offers o join public.retailers r on r.id = o.retailer_id
 where r.slug = 'amazon' and o.url ~ '/dp/[A-Z0-9]{10}'
on conflict on constraint product_identifiers_unique do nothing;
update public.ingestion_sources s set retailer_id = r.id
  from public.retailers r where r.slug = s.config ->> 'retailer_slug' and s.retailer_id is null;

-- Synthetic 120-day history for priced offers, so charts and deal quality have data: a gentle
-- random walk with retail-style prices ($x.99), changing every few days.
do $history$
declare
  o     record;
  d     integer;
  price integer;
begin
  perform setseed(0.42);
  for o in select id, price_cents, shipping_cents from public.retailer_offers where price_display = 'show' order by external_ref nulls first, url loop
    price := round(o.price_cents * (0.98 + random() * 0.14));
    for d in reverse 120..1 loop
      if d % 5 = 0 and random() < 0.6 then
        price := greatest(round(price * (0.955 + random() * 0.09) / 100) * 100 - 1, 99);
        insert into public.price_points (offer_id, observed_at, price_cents, shipping_cents, in_stock, price_display)
        values (o.id, now() - make_interval(days => d), price, o.shipping_cents, true, 'show');
      end if;
    end loop;
  end loop;
end;
$history$;

insert into public.promo_codes (retailer_id, code, title, discount_type, discount_value, min_purchase_cents, ends_at, verified_at, is_exclusive)
select r.id, p.code, p.title, p.discount_type::public.discount_type, p.discount_value, p.min_purchase_cents,
       now() + make_interval(days => p.ends_in_days), now() - make_interval(days => p.verified_days_ago), p.is_exclusive
  from jsonb_to_recordset($dev$[{"retailer_slug":"joola-com","code":"DINK15","title":"15% off sitewide","discount_type":"percent","discount_value":15,"min_purchase_cents":0,"target_kind":null,"target_slug":null,"ends_in_days":4,"verified_days_ago":0,"is_exclusive":true},{"retailer_slug":"courtside-pro-shop","code":"COURT20","title":"$20 off shoes over $100","discount_type":"amount","discount_value":2000,"min_purchase_cents":10000,"target_kind":"category","target_slug":"shoes","ends_in_days":2,"verified_days_ago":0,"is_exclusive":false},{"retailer_slug":"crbn-com","code":"CRBN10","title":"10% off the 3X series","discount_type":"percent","discount_value":10,"min_purchase_cents":0,"target_kind":"product","target_slug":"crbn-3x-power-series","ends_in_days":10,"verified_days_ago":1,"is_exclusive":false},{"retailer_slug":"baseline-sports","code":"OLDCODE","title":"Expired-verification example (hidden)","discount_type":"percent","discount_value":30,"min_purchase_cents":0,"target_kind":null,"target_slug":null,"ends_in_days":30,"verified_days_ago":30,"is_exclusive":false}]$dev$::jsonb)
       as p(retailer_slug text, code text, title text, discount_type text, discount_value int, min_purchase_cents int,
            target_kind text, target_slug text, ends_in_days int, verified_days_ago int, is_exclusive boolean)
  join public.retailers r on r.slug = p.retailer_slug;

insert into public.promo_code_targets (promo_id, product_id, category_id)
select pc.id,
       case when p.target_kind = 'product' then (select id from public.products where slug = p.target_slug) end,
       case when p.target_kind = 'category' then (select id from public.categories where slug = p.target_slug) end
  from jsonb_to_recordset($dev$[{"retailer_slug":"joola-com","code":"DINK15","title":"15% off sitewide","discount_type":"percent","discount_value":15,"min_purchase_cents":0,"target_kind":null,"target_slug":null,"ends_in_days":4,"verified_days_ago":0,"is_exclusive":true},{"retailer_slug":"courtside-pro-shop","code":"COURT20","title":"$20 off shoes over $100","discount_type":"amount","discount_value":2000,"min_purchase_cents":10000,"target_kind":"category","target_slug":"shoes","ends_in_days":2,"verified_days_ago":0,"is_exclusive":false},{"retailer_slug":"crbn-com","code":"CRBN10","title":"10% off the 3X series","discount_type":"percent","discount_value":10,"min_purchase_cents":0,"target_kind":"product","target_slug":"crbn-3x-power-series","ends_in_days":10,"verified_days_ago":1,"is_exclusive":false},{"retailer_slug":"baseline-sports","code":"OLDCODE","title":"Expired-verification example (hidden)","discount_type":"percent","discount_value":30,"min_purchase_cents":0,"target_kind":null,"target_slug":null,"ends_in_days":30,"verified_days_ago":30,"is_exclusive":false}]$dev$::jsonb) as p(retailer_slug text, code text, target_kind text, target_slug text)
  join public.retailers r on r.slug = p.retailer_slug
  join public.promo_codes pc on pc.retailer_id = r.id and pc.code = p.code
 where p.target_kind is not null;

select public.refresh_variant_price_stats(variant_id) from (select distinct variant_id from public.retailer_offers) v;

-- Dev curation: a staff pick, an editorial collection and a labelled sponsored placement.
update public.deals d set is_staff_pick = true
  from public.product_variants v join public.products p on p.id = v.product_id
 where d.variant_id = v.id and d.status = 'active' and p.slug = 'selkirk-vanguard-power-air-invikta';

insert into public.collections (slug, title, subtitle, eyebrow, sort)
values ('court-shoes-on-sale', 'Court shoes on sale', 'Pickleball-specific shoes at their best prices', 'STAFF PICKS · UPDATED DAILY', 1);
insert into public.collection_items (collection_id, product_id, sort)
select c.id, p.id, row_number() over (order by p.name)
  from public.collections c, public.products p join public.categories cat on cat.id = p.category_id
 where c.slug = 'court-shoes-on-sale' and cat.slug = 'shoes';

insert into public.placements (kind, deal_id, campaign, sort)
select 'sponsored_deal', d.id, 'CRBN', 1
  from public.deals d join public.product_variants v on v.id = d.variant_id join public.products p on p.id = v.product_id
 where d.status = 'active' and p.slug = 'crbn-3x-power-series' and v.label = '14mm';

-- Dev marketplace (local only): fictional sellers around Sarasota, FL with pre-owned listings.
-- Locations are snapped exactly as set_listing_location does (D2). No photos: the app shows
-- placeholder art for listings without images.
do $market$
declare
  sellers text[] := array['Marcus T.', 'Priya K.', 'Jordan R.'];
  ids uuid[] := array[gen_random_uuid(), gen_random_uuid(), gen_random_uuid()];
  i int;
  r record;
  lid uuid;
begin
  for i in 1..3 loop
    insert into auth.users (instance_id, id, aud, role, email, email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
                            created_at, updated_at, confirmation_token, recovery_token, email_change, email_change_token_new)
    values ('00000000-0000-0000-0000-000000000000', ids[i], 'authenticated', 'authenticated', format('seller%s@pickledeals.test', i),
            now(), '{"provider":"email","providers":["email"]}', '{}', now() - interval '200 days', now(), '', '', '', '');
    -- Identities let the dev sellers sign in with an email code too (two-account chat testing).
    insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (ids[i]::text, ids[i], jsonb_build_object('sub', ids[i]::text, 'email', format('seller%s@pickledeals.test', i), 'email_verified', true),
            'email', now(), now(), now());
    update public.profiles set display_name = sellers[i], display_name_source = 'provided', member_since = now() - interval '200 days' where id = ids[i];
  end loop;

  for r in select * from (values
      (1, 'joola-perseus-pro-iv', '16mm', null, 'excellent', 15000, true, false, 27.399, -82.401, 'Lakewood Ranch, FL', 2, 'About 15 sessions on it — moved to the 14mm. Edge guard is clean, face still has good grit. Original cover included.'),
      (2, 'selkirk-vanguard-power-air-invikta', '16mm', null, 'excellent', 12500, true, false, 27.402, -82.395, 'Lakewood Ranch, FL', 4, 'Light use, one small scuff on the edge guard. Pickup weekday evenings.'),
      (3, 'asics-gel-renma', 'Standard', null, 'like_new', 7000, true, false, 27.336, -82.531, 'Sarasota, FL', 1, 'Size 10.5, worn twice. Too narrow for me.'),
      (1, 'lobster-pickle-elite', 'Standard', null, 'good', 52000, true, false, 27.498, -82.575, 'Bradenton, FL', 9, 'Works perfectly; battery holds about 3 hours. Remote included.'),
      (2, 'crbn-3x-power-series', '16mm', null, 'like_new', 13000, true, true, 27.341, -82.540, 'Sarasota, FL', 3, 'Played twice, switching to 14mm. Happy to ship.'),
      (3, 'selkirk-core-line-backpack', 'Standard', null, 'excellent', 4500, true, true, 27.100, -82.454, 'Venice, FL', 6, 'Clean, all zippers work.'),
      (1, 'joola-perseus-pro-iv', '16mm', null, 'like_new', 14500, false, true, 27.950, -82.457, 'Tampa, FL', 5, 'Ships only — like new, under 5 sessions.'),
      (2, null, null, 'Wooden practice paddle (1990s)', 'fair', 2000, true, false, 27.336, -82.530, 'Sarasota, FL', 7, 'Old-school wooden paddle, fun for drills. Heavy.')
    ) as t(seller, product_slug, variant_label, custom_title, cond, price, pickup, ships, lat, lng, area, days_ago, body)
  loop
    insert into public.listings (seller_id, product_id, variant_id, category_id, custom_title, condition, price_cents,
                                 description, pickup, ships, status, published_at, created_at)
    select ids[r.seller], p.id, v.id, coalesce(p.category_id, (select id from public.categories where slug = 'paddles')),
           r.custom_title, r.cond::public.listing_condition, r.price, r.body, r.pickup, r.ships,
           case when r.product_slug = 'lobster-pickle-elite' then 'pending' else 'active' end::public.listing_status,
           now() - make_interval(days => r.days_ago), now() - make_interval(days => r.days_ago)
      from (select 1) one
      left join public.products p on p.slug = r.product_slug
      left join public.product_variants v on v.product_id = p.id and v.label = r.variant_label
    returning id into lid;
    insert into public.listing_private (listing_id) values (lid);
    insert into public.listing_locations (listing_id, public_point, geohash6, area_label)
    select lid, s.point, s.geohash, r.area from public.snap_point(r.lat, r.lng, 6) s;
    -- D3: custom items wait in the admin catalog queue, exactly as publish_listing queues them.
    if r.product_slug is null then
      insert into public.listing_catalog_reviews (listing_id, suggestions)
      values (lid, public.suggest_catalog_matches(r.custom_title, null));
    end if;
  end loop;
  -- One sold listing so "what it sells for" has history.
  update public.listings set status = 'sold', sold_price_cents = 13500, sold_at = now() - interval '3 days'
   where id = (select l.id from public.listings l join public.products p on p.id = l.product_id
                where p.slug = 'joola-perseus-pro-iv' and l.price_cents = 14500);

  -- A demo thread (Phase 8): Priya asks Marcus about his Perseus. Inserted as the participants,
  -- through the same triggers the app uses (previews, read state, Realtime, push rows).
  lid := (select l.id from public.listings l join public.products p on p.id = l.product_id
           where p.slug = 'joola-perseus-pro-iv' and l.price_cents = 15000);
  insert into public.conversations (id, listing_id, buyer_id, seller_id) values (gen_random_uuid(), lid, ids[2], ids[1])
  returning id into lid;
  insert into public.conversation_participants (conversation_id, user_id, role) values (lid, ids[2], 'buyer'), (lid, ids[1], 'seller');
  insert into public.messages (conversation_id, sender_id, body) values
    (lid, ids[2], 'Hi! Is this still available?'),
    (lid, ids[1], 'Yes! About 15 sessions on it, edge guard is clean.'),
    (lid, ids[2], 'Great. Could I see it this weekend?');
end;
$market$;

